async function checkPremiumWithCache(userId: string): Promise<boolean> {
  const cached = premiumCache.get(userId);
  if (cached && cached.expiresAt > Date.now()) return cached.hasPremium;
  const hasPremium = await subscriptionService.hasPremiumAccess(userId);
  premiumCache.set(userId, { hasPremium, expiresAt: Date.now() + 60000 });
  return hasPremium;
}

private validatePayment(token: string, amount: number): string | null {
  if (!token || token.trim().length === 0) return 'Invalid payment token';
  if (amount <= 0) return 'Amount must be greater than zero';
  if (amount > 999999) return 'Amount exceeds maximum allowed';
  return null;
}

